-- nv_model_catalog: model registry for the LLM router
-- Source of truth: Replit Postgres 2026-05-09
-- Idempotent: safe to re-run

CREATE TABLE IF NOT EXISTS nv_model_catalog (
  id                 SERIAL PRIMARY KEY,
  model_id           VARCHAR(200) NOT NULL UNIQUE,
  provider_id        VARCHAR(100),
  display_name       VARCHAR(255) NOT NULL,
  context_window     INTEGER,
  max_output_tokens  INTEGER,
  supports_vision    BOOLEAN DEFAULT false,
  supports_tools     BOOLEAN DEFAULT false,
  cost_per_1k_in     DOUBLE PRECISION,
  cost_per_1k_out    DOUBLE PRECISION,
  is_active          BOOLEAN NOT NULL DEFAULT true,
  created_at         TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_nv_model_catalog_provider ON nv_model_catalog(provider_id);
CREATE INDEX IF NOT EXISTS idx_nv_model_catalog_active ON nv_model_catalog(is_active) WHERE is_active = true;

-- Seed / upsert from Replit source-of-truth

-- Verification
SELECT COUNT(*) AS total_models, COUNT(*) FILTER (WHERE is_active) AS active FROM nv_model_catalog;
